package utb.fai;

import java.net.URI;
import java.net.URISyntaxException;

public class App {

	/** Výchozí maximální hloubka zanoření, pokud není zadán args[1]. */
	static final int DEFAULT_MAX_DEPTH = 2;

	public static void main(String[] args) {
		URI startURI = parseStartURI(args);
		if (startURI == null) {
			return;
		}
		int maxDepth = parseMaxDepth(args);
		Log.setLevel(parseDebugLevel(args));
		Log.info("Start: " + startURI + ", maxDepth=" + maxDepth + ", debugLevel=" + Log.getLevel());

		String startUrl = Crawler.normalize(startURI.toString());
		if (startUrl == null) {
			System.err.println("Chyba: startovní URL nelze procházet (není http/https nebo odkazuje na soubor): "
					+ startURI);
			return;
		}

		WordCounter wordCounter = new WordCounter();
		try {
			Crawler crawler = new Crawler(new PageFetcher(), maxDepth, wordCounter);
			crawler.crawl(startUrl);
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			System.err.println("Procházení přerušeno.");
		} catch (Exception e) {
			System.err.println("Zachycena neošetřená výjimka, končíme...");
			e.printStackTrace();
		}

		// I po chybě vypíšeme to, co se stihlo spočítat (případně nic).
		Log.info("Různých slov: " + wordCounter.distinctWords() + ", vypisuji " + TOP_WORDS
				+ " nejčastějších:");
		printTopWords(wordCounter);
	}

	/** Počet vypisovaných nejčastějších slov. */
	static final int TOP_WORDS = 20;

	/**
	 * Vypíše nejčastější slova na System.out ve formátu "slovo;počet". Před tím
	 * ztlumí ladicí výpisy, aby se za tabulku nic nedostalo.
	 */
	static void printTopWords(WordCounter wordCounter) {
		Log.mute();
		StringBuilder sb = new StringBuilder();
		for (var entry : wordCounter.top(TOP_WORDS)) {
			sb.append(entry.getKey()).append(';').append(entry.getValue()).append(System.lineSeparator());
		}
		System.out.print(sb);
		System.out.flush();
	}

	/**
	 * Zpracuje args[0] - startovní URL. Musí jít o absolutní http(s) URL s hostem.
	 * Prázdná cesta se doplní na "/" (např. "http://example.com" -> "http://example.com/").
	 *
	 * @return startovní URI, nebo null, pokud parametr chybí či je nevalidní
	 *         (chyba je už vypsaná na System.err)
	 */
	static URI parseStartURI(String[] args) {
		if (args.length < 1 || args[0].isBlank()) {
			System.err.println("Chyba: chybí povinný parametr - startovní URL.");
			System.err.println("Použití: java -jar app-all.jar <URL> [maxDepth=" + DEFAULT_MAX_DEPTH
					+ "] [debugLevel=0 (0 vypnuto, 1 navštívené URL a chyby, 2 podrobně)]");
			return null;
		}
		String raw = args[0].trim();
		try {
			URI uri = new URI(raw);
			String scheme = uri.getScheme();
			if (scheme == null || !(scheme.equalsIgnoreCase("http") || scheme.equalsIgnoreCase("https"))) {
				System.err.println("Chyba: URL musí začínat http:// nebo https:// - zadáno: " + raw);
				return null;
			}
			if (uri.getHost() == null) {
				System.err.println("Chyba: URL neobsahuje platný název serveru - zadáno: " + raw);
				return null;
			}
			if (uri.getRawPath() == null || uri.getRawPath().isEmpty()) {
				// skládáme z "raw" částí, aby se už escapované znaky nekódovaly znovu
				String query = uri.getRawQuery() != null ? "?" + uri.getRawQuery() : "";
				uri = new URI(scheme + "://" + uri.getRawAuthority() + "/" + query);
			}
			return uri.normalize();
		} catch (URISyntaxException e) {
			System.err.println("Chyba: nevalidní URL \"" + raw + "\" - " + e.getReason());
			return null;
		}
	}

	/**
	 * Zpracuje args[1] - maximální hloubku zanoření. Nepovinný; když chybí,
	 * nejde parsovat nebo je záporný, použije se {@link #DEFAULT_MAX_DEPTH}.
	 */
	static int parseMaxDepth(String[] args) {
		if (args.length < 2) {
			return DEFAULT_MAX_DEPTH;
		}
		try {
			int depth = Integer.parseInt(args[1].trim());
			if (depth < 0) {
				System.err.println("Varování: hloubka nesmí být záporná (" + args[1]
						+ "), používám výchozí " + DEFAULT_MAX_DEPTH + ".");
				return DEFAULT_MAX_DEPTH;
			}
			return depth;
		} catch (NumberFormatException e) {
			System.err.println("Varování: neplatná hloubka \"" + args[1]
					+ "\", používám výchozí " + DEFAULT_MAX_DEPTH + ".");
			return DEFAULT_MAX_DEPTH;
		}
	}

	/**
	 * Zpracuje args[2] - úroveň ladění (viz {@link Log}). Nepovinný; když chybí,
	 * nejde parsovat nebo je záporný, ladění je vypnuté (0).
	 */
	static int parseDebugLevel(String[] args) {
		if (args.length < 3) {
			return Log.OFF;
		}
		try {
			int level = Integer.parseInt(args[2].trim());
			if (level >= 0) {
				return level;
			}
		} catch (NumberFormatException e) {
			// varování níže
		}
		System.err.println("Varování: neplatná úroveň ladění \"" + args[2] + "\", ladění vypínám (0).");
		return Log.OFF;
	}

}
